def _descriptor_clone(function, namespace):
    result=_descriptor_types.FunctionType(function.__code__,namespace,function.__name__,function.__defaults__,function.__closure__)
    result.__kwdefaults__=function.__kwdefaults__
    return result


def _descriptor_relative(module):
    """Equivalent canonical POSIX fast path; uncertain values run the whole original."""
    import ast, os
    raw=Path(module.__file__).read_text()
    nodes=[n for n in ast.parse(raw).body if isinstance(n,ast.FunctionDef)and n.name=='relative']
    if len(nodes)!=1 or _descriptor_hashlib.sha256(ast.get_source_segment(raw,nodes[0]).encode()).hexdigest()!='486c47ebbe2e6cfc392bde908003baf7559fd70d2f6ed17684f2ba34340fac41':
        raise ValueError('whole original inner relative validator source')
    original=module.relative
    if os.name!='posix':return original
    def relative(value):
        # This validates text only: no filesystem/path observations, hashes,
        # mount identities, descriptors or successful strings are retained.
        if type(value)is str and value and '\0'not in value and all(part not in('','.','..')for part in value.split('/')):
            return value
        return original(value)
    relative.__wrapped__=original
    return relative



