_DESCRIPTOR_ROOT_PROFILE_NAME = 'SOURCE02C_NORMAL_ROOT_DIAGNOSTIC_EXACT_INVERSE_V1'

def _descriptor_root_bytes(raw, require):
    # Only this exact whole diagnostic Source qualifies for the finite inverse.
    # Historical587/607 bytes still reach the original whole-source pin below.
    if (len(raw), _descriptor_hashlib.sha256(raw).hexdigest()) == _DESCRIPTOR_ROOT_PROFILE:
        for offset, length, digest, original in _DESCRIPTOR_ROOT_INVERSE:
            require(0 <= offset <= len(raw) and 0 <= length <= len(raw)-offset
                    and _descriptor_hashlib.sha256(raw[offset:offset+length]).hexdigest() == digest,
                    'exact diagnostic root inverse span')
            raw = raw[:offset] + original + raw[offset+length:]
    return raw


def _descriptor_bind(original, query):
    """Whole original graph/hash/lease checks, with private mount/text APIs only."""
    for name,module in (('full_root',original.roots),('measure_copy',original.measure_copy),('aux_checkpoint',original.aux)):
        raw=Path(module.__file__).read_bytes()
        if name=='full_root':raw=_descriptor_root_bytes(raw, original.aux.need)
        if name=='full_root' and b'max_packages: int = 607' in raw:
            original.aux.need(raw.count(b'max_packages: int = 607')==1,'one selected607 package default')
            raw=raw.replace(b'max_packages: int = 607',b'max_packages: int = 587',1)
        size,digest=_DESCRIPTOR_PINS[name]
        original.aux.need(len(raw)==size and _descriptor_hashlib.sha256(raw).hexdigest()==digest,'whole updater descriptor source: '+name)
    roots=_descriptor_types.SimpleNamespace(**vars(original.roots))
    roots._mount_id=query(original.roots._mount_id)
    roots.installer=_descriptor_types.SimpleNamespace(**vars(original.roots.installer))
    roots.installer.relative=_descriptor_relative(original.roots.installer)
    root_space=dict(vars(original.roots),_mount_id=roots._mount_id,installer=roots.installer)
    text_methods=('observe','_projected_paths','_path_set','_group_graph','check_hardlink_preservation')
    for name in text_methods:root_space[name]=_descriptor_clone(getattr(original.roots,name),root_space)
    for name in text_methods:setattr(roots,name,root_space[name])
    # Reader methods otherwise retain the separate original measure_copy globals.
    walk_space=dict(vars(original.measure_copy),roots=roots)
    for name in ('_parent','_root_check','_source_alias'):
        function=getattr(original.measure_copy,name)
        walk_space[name]=(_descriptor_contextmanager(_descriptor_clone(function.__wrapped__,walk_space))
                          if name=='_parent' else _descriptor_clone(function,walk_space))
    walk=_descriptor_types.SimpleNamespace(**walk_space)
    aux=original.aux;aux_space=dict(vars(aux),roots=roots,copy=walk)
    methods={name:_descriptor_clone(value,aux_space) if isinstance(value,_descriptor_types.FunctionType) else value
             for name,value in vars(aux.Reader).items() if name not in ('__dict__','__weakref__')}
    aux_space['Reader']=type('_UpdaterDescriptorReader',(),methods)
    for name in ('checkpoint','load_comparator'):
        aux_space[name]=_descriptor_clone(getattr(aux,name),aux_space)
    auxiliary=_descriptor_types.SimpleNamespace(**aux_space)
    copy_space=dict(vars(original),roots=roots,aux=auxiliary)
    # One shared private dictionary is essential: copied_root -> copy_data ->
    # _copy_binding must reach these functions, not their old module globals.
    for name in ('_isolated','_copy_binding','copy_data','copied_root'):
        copy_space[name]=_descriptor_clone(getattr(original,name),copy_space)
    private_isolated=copy_space['_isolated']
    def isolated(source,expected):
        module=private_isolated(source,expected)
        if Path(source)==Path(original.disposable_copy.__file__):
            auxiliary.need(expected==original.LIFETIME_SHA256,'whole original lifetime source')
            # This is the newly compiled exact pinned lifetime module only.
            # Its original copied_root/_same/_empty bodies share these globals.
            module.roots=roots
        if Path(source)==Path(original.measure_copy.__file__):
            auxiliary.need(expected==original.COPY_SHA256,'whole original cost copier source')
            module=_updater_copy_cost.bind(module,_UPDATER_COST_COPIER,_DESCRIPTOR_PINS['measure_copy'])
        return module
    isolated.__wrapped__=private_isolated
    copy_space['_isolated']=isolated
    return _descriptor_types.SimpleNamespace(**copy_space)


def _mount600(original):
    import ctypes
    import errno
    import os
    import sys
    # Linux statx UAPI: mask offset0, mnt_id offset144, fixed256-byte record.
    # Request ordinary STATX_MNT_ID, never the distinct MNT_ID_UNIQUE namespace.
    class Statx600(ctypes.Structure):
        _fields_=[('mask',ctypes.c_uint32),('prefix',ctypes.c_ubyte*140),
                  ('mnt_id',ctypes.c_uint64),('reserved',ctypes.c_ubyte*104)]
    supported=(sys.platform=='linux' and sys.byteorder=='little' and ctypes.sizeof(ctypes.c_void_p)==8 and
               os.uname().machine in ('aarch64','x86_64') and ctypes.sizeof(Statx600)==256 and Statx600.mnt_id.offset==144)
    libc=ctypes.CDLL(None,use_errno=True) if supported else None
    call=getattr(libc,'statx',None)
    if call is not None:
        call.argtypes=(ctypes.c_int,ctypes.c_char_p,ctypes.c_int,ctypes.c_uint,ctypes.POINTER(Statx600))
        call.restype=ctypes.c_int
    empty_path=ctypes.c_char_p(b'');empty_flags=ctypes.c_int(0x1000);mount_mask=ctypes.c_uint(0x1000)
    checked=False
    def query(descriptor,limits):
        nonlocal call,checked
        limits.tick()
        if call is None:_updater_copy_cost.mount('fallback');return original(descriptor,limits)
        result=Statx600()
        if call(descriptor,empty_path,empty_flags,mount_mask,ctypes.byref(result))!=0:
            error=ctypes.get_errno()
            if error in (errno.ENOSYS,errno.EINVAL,errno.EOPNOTSUPP,errno.EPERM):
                call=None;_updater_copy_cost.mount('fallback');return original(descriptor,limits)
            raise OSError(error,'descriptor statx mount query failed')
        if not result.mask&0x1000:
            call=None;_updater_copy_cost.mount('fallback');return original(descriptor,limits)
        if not result.mnt_id:raise ValueError('descriptor statx mount identity unavailable')
        _updater_copy_cost.mount('statx')
        if not checked:
            if result.mnt_id!=original(descriptor,limits):raise ValueError('descriptor mount identity APIs differ')
            checked=True
        return result.mnt_id
    return query


